CREATE DATABASE IF NOT EXISTS spendwise; USE spendwise;
CREATE TABLE IF NOT EXISTS users(user_id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(category_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,category_name VARCHAR(100) NOT NULL,category_type ENUM('Income','Expense') NOT NULL,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,UNIQUE(user_id,category_name,category_type));
CREATE TABLE IF NOT EXISTS transactions(transaction_id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,category_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL,transaction_type ENUM('Income','Expense') NOT NULL,description VARCHAR(255),transaction_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE,FOREIGN KEY(category_id) REFERENCES categories(category_id) ON DELETE CASCADE);
